const input = require("fs").readFileSync(0, "utf8");

function sumNumbers(nums) {
  let total = 0;
  for (const num of nums) {
    total += num;
  }
  return total;
}

const [n, ...nums] = input.trim().split(/\s+/).map(Number);
const total = sumNumbers(nums);
console.log(total);
console.log((total / n).toFixed(2));

