package main

import "fmt"

func sumNumbers(nums []int) int {
	total := 0
	for _, num := range nums {
		total += num
	}
	return total
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	total := sumNumbers(nums)
	fmt.Println(total)
	fmt.Printf("%.2f\n", float64(total)/float64(n))
}
